import MiniSearch from "minisearch";
// Resolved relative to output/<Module>/ at build time (same convention as
// MarkdownContent.js). The index is generated by web/scripts/render-docs.mjs.
import index from "../../web/docs/search-index.json";

const mini = new MiniSearch({
  fields: ["heading", "text", "docTitle"],
  storeFields: ["path", "anchor", "docTitle", "heading", "text"],
  searchOptions: {
    boost: { heading: 3, docTitle: 2 },
    prefix: true,
    fuzzy: 0.2,
    combineWith: "AND",
  },
});
mini.addAll(index);

// A short context window around the first matching term in the section body.
const snippetOf = (text, query) => {
  const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
  const lower = text.toLowerCase();
  let pos = -1;
  for (const t of terms) {
    const i = lower.indexOf(t);
    if (i >= 0 && (pos < 0 || i < pos)) pos = i;
  }
  const start = pos < 0 ? 0 : Math.max(0, pos - 40);
  let s = text.slice(start, start + 180).trim();
  if (start > 0) s = "… " + s;
  if (start + 180 < text.length) s = s + " …";
  return s;
};

export const searchImpl = (query) => {
  const q = query.trim();
  if (!q) return [];
  return mini.search(q).slice(0, 40).map((r) => ({
    path: r.path,
    anchor: r.anchor,
    docTitle: r.docTitle,
    heading: r.heading,
    snippet: snippetOf(r.text || "", q),
  }));
};
